def trigger(self, dag_id: str, session: Session = NEW_SESSION):
    """Triggers DAG Run."""
    run_id = request.values.get("run_id", "")
    origin = get_safe_url(request.values.get("origin"))
    unpause = request.values.get("unpause")
    request_conf = request.values.get("conf")
    request_execution_date = request.values.get("execution_date", default=timezone.utcnow().isoformat())
    is_dag_run_conf_overrides_params = conf.getboolean("core", "dag_run_conf_overrides_params")
    dag = get_airflow_app().dag_bag.get_dag(dag_id)
    dag_orm: DagModel = session.query(DagModel).filter(DagModel.dag_id == dag_id).first()

    # Prepare form fields with param struct details to render a proper form with schema information
    form_fields = {}
    for k, v in dag.params.items():
        form_fields[k] = v.dump()
        # If no schema is provided, auto-detect on default values
        if "schema" not in form_fields[k]:
            form_fields[k]["schema"] = {}
        if "type" not in form_fields[k]["schema"]:
            if isinstance(form_fields[k]["value"], bool):
                form_fields[k]["schema"]["type"] = "boolean"
            elif isinstance(form_fields[k]["value"], int):
                form_fields[k]["schema"]["type"] = ["integer", "null"]
            elif isinstance(form_fields[k]["value"], list):
                form_fields[k]["schema"]["type"] = ["array", "null"]
            elif isinstance(form_fields[k]["value"], dict):
                form_fields[k]["schema"]["type"] = ["object", "null"]
        # Mark markup fields as safe
        if (
            "description_html" in form_fields[k]["schema"]
            and form_fields[k]["schema"]["description_html"]
        ):
            form_fields[k]["description"] = Markup(form_fields[k]["schema"]["description_html"])
        if "custom_html_form" in form_fields[k]["schema"]:
            form_fields[k]["schema"]["custom_html_form"] = Markup(
                form_fields[k]["schema"]["custom_html_form"]
            )
    ui_fields_defined = any("const" not in f["schema"] for f in form_fields.values())

    if not dag_orm:
        flash(f"Cannot find dag {dag_id}")
        return redirect(origin)

    if dag_orm.has_import_errors:
        flash(f"Cannot create dagruns because the dag {dag_id} has import errors", "error")
        return redirect(origin)

    recent_runs = (
        session.query(
            DagRun.conf, func.max(DagRun.run_id).label("run_id"), func.max(DagRun.execution_date)
        )
        .filter(
            DagRun.dag_id == dag_id,
            DagRun.run_type == DagRunType.MANUAL,
            DagRun.conf.isnot(None),
        )
        .group_by(DagRun.conf)
        .order_by(func.max(DagRun.execution_date).desc())
        .limit(5)
    )
    recent_confs = {
        run_id: json.dumps(run_conf)
        for run_id, run_conf in ((run.run_id, run.conf) for run in recent_runs)
        if isinstance(run_conf, dict) and any(run_conf)
    }

    if request.method == "GET" and ui_fields_defined:
        # Populate conf textarea with conf requests parameter, or dag.params
        default_conf = ""

        doc_md = wwwutils.wrapped_markdown(getattr(dag, "doc_md", None))
        form = DateTimeForm(data={"execution_date": request_execution_date})

        if request_conf:
            default_conf = request_conf
        else:
            try:
                default_conf = json.dumps(
                    {str(k): v.resolve(suppress_exception=True) for k, v in dag.params.items()},
                    indent=4,
                    ensure_ascii=False,
                )
            except TypeError:
                flash("Could not pre-populate conf field due to non-JSON-serializable data-types")
        return self.render_template(
            "airflow/trigger.html",
            form_fields=form_fields,
            dag=dag,
            dag_id=dag_id,
            origin=origin,
            conf=default_conf,
            doc_md=doc_md,
            form=form,
            is_dag_run_conf_overrides_params=is_dag_run_conf_overrides_params,
            recent_confs=recent_confs,
        )

    try:
        execution_date = timezone.parse(request_execution_date)
    except ParserError:
        flash("Invalid execution date", "error")
        form = DateTimeForm(data={"execution_date": timezone.utcnow().isoformat()})
        return self.render_template(
            "airflow/trigger.html",
            form_fields=form_fields,
            dag=dag,
            dag_id=dag_id,
            origin=origin,
            conf=request_conf if request_conf else {},
            form=form,
            is_dag_run_conf_overrides_params=is_dag_run_conf_overrides_params,
            recent_confs=recent_confs,
        )

    dr = DagRun.find_duplicate(dag_id=dag_id, run_id=run_id, execution_date=execution_date)
    if dr:
        if dr.run_id == run_id:
            message = f"The run ID {run_id} already exists"
        else:
            message = f"The logical date {execution_date} already exists"
        flash(message, "error")
        return redirect(origin)

    # Flash a warning when slash is used, but still allow it to continue on.
    if run_id and "/" in run_id:
        flash(
            "Using forward slash ('/') in a DAG run ID is deprecated. Note that this character "
            "also makes the run impossible to retrieve via Airflow's REST API.",
            "warning",
        )

    run_conf = {}
    if request_conf:
        try:
            run_conf = json.loads(request_conf)
            if not isinstance(run_conf, dict):
                flash("Invalid JSON configuration, must be a dict", "error")
                form = DateTimeForm(data={"execution_date": execution_date})
                return self.render_template(
                    "airflow/trigger.html",
                    form_fields=form_fields,
                    dag=dag,
                    dag_id=dag_id,
                    origin=origin,
                    conf=request_conf,
                    form=form,
                    is_dag_run_conf_overrides_params=is_dag_run_conf_overrides_params,
                    recent_confs=recent_confs,
                )
        except json.decoder.JSONDecodeError:
            flash("Invalid JSON configuration, not parseable", "error")
            form = DateTimeForm(data={"execution_date": execution_date})
            return self.render_template(
                "airflow/trigger.html",
                form_fields=form_fields,
                dag=dag,
                dag_id=dag_id,
                origin=origin,
                conf=request_conf,
                form=form,
                is_dag_run_conf_overrides_params=is_dag_run_conf_overrides_params,
                recent_confs=recent_confs,
            )

    if unpause and dag.get_is_paused():
        dag_model = models.DagModel.get_dagmodel(dag_id)
        if dag_model is not None:
            dag_model.set_is_paused(is_paused=False)

    try:
        dag.create_dagrun(
            run_type=DagRunType.MANUAL,
            execution_date=execution_date,
            data_interval=dag.timetable.infer_manual_data_interval(run_after=execution_date),
            state=State.QUEUED,
            conf=run_conf,
            external_trigger=True,
            dag_hash=get_airflow_app().dag_bag.dags_hash.get(dag_id),
            run_id=run_id,
        )
    except (ValueError, ParamValidationError) as ve:
        flash(f"{ve}", "error")
        form = DateTimeForm(data={"execution_date": execution_date})
        # Take over "bad" submitted fields for new form display
        for k, v in form_fields.items():
            form_fields[k]["value"] = run_conf[k]
        return self.render_template(
            "airflow/trigger.html",
            form_fields=form_fields,
            dag=dag,
            dag_id=dag_id,
            origin=origin,
            conf=request_conf,
            form=form,
            is_dag_run_conf_overrides_params=is_dag_run_conf_overrides_params,
        )

    flash(f"Triggered {dag_id}, it should start any moment now.")
    return redirect(origin)

def static(path):
    """
    Create a page handler to serve static files. Disable authentication.
    """
    assert isinstance(path, str)
    assert os.path.exists(path), "%r doesn't exists" % path
    content_type = None
    if os.path.isfile(path):
        # Set content-type based on filename extension
        ext = ""
        i = path.rfind('.')
        if i != -1:
            ext = path[i:].lower()
        content_type = mimetypes.types_map.get(ext, None)  # @UndefinedVariable

    @cherrypy.expose
    @cherrypy.tools.auth_form(on=False)
    @cherrypy.tools.sessions(on=False)
    @cherrypy.tools.secure_headers(on=False)
    def handler(*args, **kwargs):
        if cherrypy.request.method not in ('GET', 'HEAD'):
            return None
        filename = os.path.join(path, *args)
        assert filename.startswith(path)
        if not os.path.isfile(filename):
            return None
        return serve_file(filename, content_type)

    return handler

async def _handle(self, request: Request) -> StreamResponse:
    rel_url = request.match_info["filename"]
    try:
        filename = Path(rel_url)
        if filename.anchor:
            # rel_url is an absolute name like
            # /static/\\machine_name\c$ or /static/D:\path
            # where the static dir is totally different
            raise HTTPForbidden()
        filepath = self._directory.joinpath(filename).resolve()
        if not self._follow_symlinks:
            filepath.relative_to(self._directory)
    except (ValueError, FileNotFoundError) as error:
        # relatively safe
        raise HTTPNotFound() from error
    except HTTPForbidden:
        raise
    except Exception as error:
        # perm error or other kind!
        request.app.logger.exception(error)
        raise HTTPNotFound() from error

    # on opening a dir, load its contents if allowed
    if filepath.is_dir():
        if self._show_index:
            try:
                return Response(
                    text=self._directory_as_html(filepath), content_type="text/html"
                )
            except PermissionError:
                raise HTTPForbidden()
        else:
            raise HTTPForbidden()
    elif filepath.is_file():
        return FileResponse(filepath, chunk_size=self._chunk_size)
    else:
        raise HTTPNotFound

def _secure_path(path_tuple):
    if _has_insecure_pathelement(path_tuple):
        # belt-and-suspenders security; this should never be true
        # unless someone screws up the traversal_path code
        # (request.subpath is computed via traversal_path too)
        return None
    if any([_contains_slash(item) for item in path_tuple]):
        return None
    encoded = '/'.join(path_tuple)  # will be unicode
    return encoded

def handle_get(self) -> bool:
    if self.do_log:
        logmsg = "%-4s %s @%s" % (self.mode, self.req, self.uname)

        if "range" in self.headers:
            try:
                rval = self.headers["range"].split("=", 1)[1]
            except:
                rval = self.headers["range"]

            logmsg += " [\033[36m" + rval + "\033[0m]"

        self.log(logmsg)

    # "embedded" resources
    if self.vpath.startswith(".cpr"):
        if self.vpath.startswith(".cpr/ico/"):
            return self.tx_ico(self.vpath.split("/")[-1], exact=True)

        if self.vpath.startswith(".cpr/ssdp"):
            return self.conn.hsrv.ssdp.reply(self)

        if self.vpath.startswith(".cpr/dd/") and self.args.mpmc:
            if self.args.mpmc == ".":
                raise Pebkac(404)

            loc = self.args.mpmc.rstrip("/") + self.vpath[self.vpath.rfind("/") :]
            h = {"Location": loc, "Cache-Control": "max-age=39"}
            self.reply(b"", 301, headers=h)
            return True

        static_path = os.path.join(self.E.mod, "web/", self.vpath[5:])
        return self.tx_file(static_path)

    if "cf_challenge" in self.uparam:
        self.reply(self.j2s("cf").encode("utf-8", "replace"))
        return True

    if not self.can_read and not self.can_write and not self.can_get:
        t = "@{} has no access to [{}]"
        self.log(t.format(self.uname, self.vpath))

        if "on403" in self.vn.flags:
            ret = self.on40x(self.vn.flags["on403"], self.vn, self.rem)
            if ret == "true":
                return True
            elif ret == "false":
                return False
            elif ret == "allow":
                self.log("plugin override; access permitted")
                self.can_read = self.can_write = self.can_move = True
                self.can_delete = self.can_get = self.can_upget = True
                self.can_admin = True
            else:
                return self.tx_404(True)
        else:
            if self.vpath:
                return self.tx_404(True)

            self.uparam["h"] = ""

    if "tree" in self.uparam:
        return self.tx_tree()

    if "scan" in self.uparam:
        return self.scanvol()

    if self.args.getmod:
        if "delete" in self.uparam:
            return self.handle_rm([])

        if "move" in self.uparam:
            return self.handle_mv()

    if not self.vpath:
        if "reload" in self.uparam:
            return self.handle_reload()

        if "stack" in self.uparam:
            return self.tx_stack()

        if "ups" in self.uparam:
            return self.tx_ups()

        if "k304" in self.uparam:
            return self.set_k304()

        if "setck" in self.uparam:
            return self.setck()

        if "reset" in self.uparam:
            return self.set_cfg_reset()

        if "hc" in self.uparam:
            return self.tx_svcs()

    if "h" in self.uparam:
        return self.tx_mounts()

    # conditional redirect to single volumes
    if self.vpath == "" and not self.ouparam:
        nread = len(self.rvol)
        nwrite = len(self.wvol)
        if nread + nwrite == 1 or (self.rvol == self.wvol and nread == 1):
            if nread == 1:
                vpath = self.rvol[0]
            else:
                vpath = self.wvol[0]

            if self.vpath != vpath:
                self.redirect(vpath, flavor="redirecting to", use302=True)
                return True

    return self.tx_browser()

def lookup_path(
    self, path: str
) -> typing.Tuple[str, typing.Optional[os.stat_result]]:
    for directory in self.all_directories:
        joined_path = os.path.join(directory, path)
        if self.follow_symlink:
            full_path = os.path.abspath(joined_path)
        else:
            full_path = os.path.realpath(joined_path)
        directory = os.path.realpath(directory)
        if os.path.commonprefix([full_path, directory]) != directory:
            # Don't allow misbehaving clients to break out of the static files
            # directory.
            continue
        try:
            return full_path, os.stat(full_path)
        except (FileNotFoundError, NotADirectoryError):
            continue
    return "", None

    def get_snippet_path(self, path):
        """Get snippet path."""

        snippet = None
        for base in self.base_path:
            if os.path.exists(base):
                if os.path.isdir(base):
                    filename = os.path.join(base, path)
                    if os.path.exists(filename):
                        snippet = filename
                        break
                else:
                    basename = os.path.basename(base)
                    dirname = os.path.dirname(base)
                    if basename.lower() == path.lower():
                        filename = os.path.join(dirname, path)
                        if os.path.exists(filename):
                            snippet = filename
                            break
        return snippet

def get_artifact_handler():
    from querystring_parser import parser

    query_string = request.query_string.decode("utf-8")
    request_dict = parser.parse(query_string, normalized=True)
    run_id = request_dict.get("run_id") or request_dict.get("run_uuid")
    run = _get_tracking_store().get_run(run_id)

    if _is_servable_proxied_run_artifact_root(run.info.artifact_uri):
        artifact_repo = _get_artifact_repo_mlflow_artifacts()
        artifact_path = _get_proxied_run_artifact_destination_path(
            proxied_artifact_root=run.info.artifact_uri,
            relative_path=request_dict["path"],
        )
    else:
